{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "Identifying existing approaches used to evaluate the sustainability of evidence-based interventions in healthcare: an integrative review",
      "reason": "The title identifies the report as a review ('an integrative review'), but does not use the term 'systematic review'. The methods (text_8) clarify it is an integrative review, which the authors distinguish from a systematic review, so the title only partially satisfies identifying the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Identifying existing approaches used to evaluate the sustainability of evidence-based interventions in healthcare",
      "reason": "The title conveys the main objective (identifying approaches to evaluate sustainability) and the population/intervention focus (evidence-based interventions in healthcare)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "an integrative review",
      "reason": "The title provides supplementary methodological information by specifying the review design (integrative review), which per text_8 includes diverse data sources and both quantitative and qualitative data."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement.",
      "reason": "The background describes the current state of knowledge (implementation science maturity, sustainability definitions) and identifies the key uncertainty: limited evidence and unclear which approaches are most effective for evaluating sustainability."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "As evaluation is necessary to determine effectiveness, this review aimed to improve our understanding of how the sustainability of EBIs in healthcare is evaluated. A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research.",
      "reason": "The importance and need for the review are explicitly explained, including the knowledge gap and the benefit for healthcare leaders needing guidance on selecting theoretical approaches."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research... that were consistent with other recent synthesis work [6-10]. A recent scoping review and theory analysis [8] found 37 sustainability determinant factors",
      "reason": "Existing similar reviews (Lennox et al., recent scoping review) are identified and cited, and the need for the current review is explained by its distinct focus on evaluation approaches."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of approaches to evaluate sustainability of EBIs, not a review of intervention effects, so describing a mechanism of action of an intervention does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not evaluate a specific complex intervention's effects; it maps evaluation approaches, so a logic model of intervention components and outcomes is not required."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "table_0",
      "quote": "Articles were included if they: • Were published in a peer-review journal • Were primary research • Had explicit research design and data collection methods • Had an explicit theoretical approach for sustainability ... • Were within a healthcare setting • Evaluated the sustainability of an EBI",
      "reason": "Table 1 specifies study characteristics for eligibility: primary research, explicit design/methods, theoretical approach, healthcare setting, and sustainability evaluation of an EBI, with definitions of settings and approaches provided."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "table_0",
      "quote": "Were published in a peer-review journal ... Excluded if they: • Were secondary research • Were gray literature",
      "reason": "Publication status (peer-reviewed, not gray literature) is specified, but no dissemination year or language restriction is stated in the eligibility criteria; language restriction is only mentioned retrospectively in the Limitations section."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "table_0",
      "quote": "Did not evaluate the sustainability of an EBI or QI intervention using a defined approach",
      "reason": "This integrative review of evaluation approaches does not require outcome measurement as an eligibility criterion; the distinction between outcomes not measured vs not reported does not apply to the stated criteria."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "The two reviewers independently extracted the following variables: (1) study design, (2) evaluation type (independent versus composite), (3) sustainability definition and terms used, (4) type and name of theoretical approach...",
      "reason": "Grouping variables for synthesis (study design, evaluation type, theoretical approach type) are described via data extraction items, but explicit linkage of synthesis groups to review objective comparisons is not clearly stated."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_21",
      "quote": "We only included published studies in the English language and peer-reviewed primary studies in this review... all gray literature was excluded.",
      "reason": "Restrictions (English language, peer-reviewed, no gray literature) are mentioned, but rationales for these restrictions are only implicitly provided in the Limitations section rather than in the Methods."
    }
  ],
  "confidence": 82
}

